using System;
using Ordering.Legacy;

namespace Ordering;

/// <summary>Produces dispatch labels for an order.</summary>
public sealed class LabelPrinter
{
    private static readonly Func<string, string, string> RenderLabel = CreateRenderer();

    public string Print(Order order, string service)
    {
        // TODO: support multi-parcel orders with one label per parcel
        return RenderLabel(order.Reference, service);
    }

    private static Func<string, string, string> CreateRenderer()
    {
        var renderMethod = typeof(LabelApiV1).GetMethod(
            "Render",
            new[] { typeof(string), typeof(string) });

        if (renderMethod is null)
        {
            throw new MissingMethodException(typeof(LabelApiV1).FullName, "Render");
        }

        return (Func<string, string, string>)Delegate.CreateDelegate(
            typeof(Func<string, string, string>),
            renderMethod);
    }
}
